head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// features 로 지정할 두 가지 값 (위치 지정 없음 / 위치 지정 있음)
scwin.FEATURES_SIZE = "width=700,height=400";
scwin.FEATURES_POS = "left=100,top=100,width=700,height=400";

scwin.gVar = null;



// 이전 케이스에서 열린 팝업창 / WFrame 레이어를 닫는다.
//  · WFrame 레이어를 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    try {
        if (scwin.gVar !== null && scwin.gVar.win !== null && scwin.gVar.win.closed === false) scwin.gVar.win.close();
    } catch (e) {}

    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return false;

        WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
        return true;
    } catch (e) {}

    return false;
};



// features 값과 wframe 조합으로 advancedExcelUpload 실행
//  · 별도 팝업창은 엔진이 호출 시점에 window 이름 fileupWindow 로 생성하므로 그 자리에서 창 핸들을 한 번만 확보한다.
//    (나중에 window.open 으로 창을 다시 찾으면 이미 닫힌 경우 빈 창(about:blank)이 새로 열리므로 확보해 둔 핸들로만 판정한다.)
scwin.runCase = function (strNo, strFeatures, bUseWframe) {
    var bClosed = scwin.closeOpened();
    scwin.gVar = { "no" : strNo, "wframe" : bUseWframe, "win" : null };

    scwin.setReturnValue("[" + strNo + "] features = \"" + strFeatures + "\" , wframe = " + (bUseWframe === true ? "true" : "미설정"));

    var fnRun = function () {
        var objOptions = { "features" : strFeatures };
        if (bUseWframe === true) objOptions.wframe = true;

        var fnOpen = window.open;
        window.open = function (sUrl, sName) {
            var objWin = fnOpen.apply(window, arguments);
            if (sName === "fileupWindow") scwin.gVar.win = objWin;
            return objWin;
        };
        try {
            target1.advancedExcelUpload(objOptions);
        } finally {
            window.open = fnOpen;
        }

        // 엔진에 실제로 전달된 features 값은 업로드가 끝나면 비워지므로 호출 직후 바로 읽는다.
        scwin.printFeatures();

        setTimeout(function () { scwin.printState(0); }, 1500);
    };

    // 이전 WFrame 레이어의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 엔진에 실제로 전달된 features 값의 형태(타입)와 값 출력
scwin.printFeatures = function () {
    var strInfo = target1._excelUploadInfo;
    if (strInfo === undefined || strInfo === null || strInfo === "") {
        scwin.setReturnValue("전달된 features : 확인 불가");
        return;
    }

    var objFeatures = JSON.parse(strInfo).sFeatures;
    scwin.setReturnValue("전달된 features : " + (typeof objFeatures) + " " + JSON.stringify(objFeatures));
};



// 열린 Excel 파일 선택 팝업의 실제 위치 / 크기 출력
//  · wframe true 는 화면 내 레이어(GridView ID + _excelPop)이므로 화면상의 left / top / width / height 를 그대로 측정한다.
//  · wframe 미설정은 별도 팝업창이므로 창 크기만 출력한다. (창 위치는 실브라우저에서 확인한다.)
scwin.printState = function (nRetry) {
    nRetry = nRetry || 0;

    if (scwin.gVar.wframe === true) {
        var objLayer = document.querySelector("[id$='_excelPop']");
        if (objLayer === null) {
            if (nRetry < 8) {
                setTimeout(function () { scwin.printState(nRetry + 1); }, 500);
                return;
            }
            scwin.setReturnValue("레이어 위치 / 크기 : 없음 (레이어가 확인되지 않음)");
            scwin.setReturnValue("");
            return;
        }

        var objRect = objLayer.getBoundingClientRect();
        scwin.setReturnValue("레이어 위치 / 크기 : left=" + Math.round(objRect.left) + " , top=" + Math.round(objRect.top) + " , width=" + Math.round(objRect.width) + " , height=" + Math.round(objRect.height));
        scwin.setReturnValue("");
        return;
    }

    var objWin = scwin.gVar.win;
    if (objWin === null || objWin.closed === true) {
        if (nRetry < 8) {
            setTimeout(function () { scwin.printState(nRetry + 1); }, 500);
            return;
        }
        scwin.setReturnValue("팝업창 크기 : 없음 (팝업창이 확인되지 않음)");
        scwin.setReturnValue("");
        return;
    }

    scwin.setReturnValue("팝업창 크기 : width=" + objWin.outerWidth + " , height=" + objWin.outerHeight + "  (창 위치는 실브라우저에서 확인)");
    scwin.setReturnValue("");
};



// Ⓐ 크기만 지정 + wframe true
scwin.btn_caseA_onclick = function () {
    scwin.runCase("Ⓐ", scwin.FEATURES_SIZE, true);
};

// Ⓑ 크기만 지정 + wframe 미설정
scwin.btn_caseB_onclick = function () {
    scwin.runCase("Ⓑ", scwin.FEATURES_SIZE, false);
};

// Ⓒ 위치 + 크기 지정 + wframe true
scwin.btn_caseC_onclick = function () {
    scwin.runCase("Ⓒ", scwin.FEATURES_POS, true);
};

// Ⓓ 위치 + 크기 지정 + wframe 미설정
scwin.btn_caseD_onclick = function () {
    scwin.runCase("Ⓓ", scwin.FEATURES_POS, false);
};
